var draw = SVG().addTo(document.getElementById('container')).viewbox(0, 0, 900, 770);
var PI = Math.PI;
var ACCENT = '#1565c0', HCOL = '#d32f2f', DARK = '#111';

/* ─────────── Top: four faithful panels ─────────── */
var headings = ['No triangle, a < h', 'Right triangle, a = h', 'Two triangles, a > h, a < b', 'One triangle, a ≥ b'];
var letters = ['(a)', '(b)', '(c)', '(d)'];
var popups = [
  ['No triangle (a < h)', 'Side a is shorter than the altitude h = b·sin α, the closest γ ever gets to the base. The segment dangles with a gap, so the figure can never close — no triangle exists.'],
  ['Right triangle (a = h)', 'When a exactly equals h, it just touches the base at the one perpendicular point. Exactly one triangle exists, and it is a right triangle.'],
  ['Two triangles (h < a < b)', 'Side a is long enough to reach the base but shorter than b, so it can swing down on either side of the altitude foot. Both positions close — two different triangles satisfy the same SSA data.'],
  ['One triangle (a ≥ b)', 'Once a is at least as long as b, the left-hand landing point falls behind α and is not valid. Only one triangle remains — the SSA ambiguity disappears.']
];

function italic(g, str, x, y, size, anchor) {
  return g.text(str).font({ size: size || 15, 'font-style': 'italic', 'font-family': 'Georgia, serif' })
    .attr({ 'text-anchor': anchor || 'start', fill: DARK }).move(x, y);
}
function alphaArc(g, cx, cy, r, angDeg, col, w) {
  var t = angDeg * PI / 180;
  g.path('M ' + (cx + r) + ' ' + cy + ' A ' + r + ' ' + r + ' 0 0 0 ' +
    (cx + r * Math.cos(t)) + ' ' + (cy - r * Math.sin(t)))
    .fill('none').stroke({ color: col || DARK, width: w || 1.5 });
}

(function drawPanels() {
  var baseY = 150, ang = 40, bpx = 118;
  var c = Math.cos(ang * PI / 180), s = Math.sin(ang * PI / 180);
  for (var i = 0; i < 4; i++) {
    (function (i) {
      var ox = 12 + i * 224;
      var g = draw.group().css('cursor', 'pointer');
      g.on('click', function () { showPopup(popups[i][0], popups[i][1]); });
      g.text(headings[i]).font({ size: 13.5, 'font-family': 'Georgia, serif' })
        .attr({ 'text-anchor': 'middle' }).center(ox + 96, 22);
      var Ax = ox + 15, Ay = baseY;
      var Gx = Ax + bpx * c, Gy = Ay - bpx * s; // apex γ ≈ (ox+105, 74)
