      alphaArc(g, Ax, Ay, 24, ang);
      italic(g, 'α', ox - 2, baseY + 4, 16);
      g.line(Ax, Ay, Gx, Gy).stroke({ color: DARK, width: 2 });
      italic(g, 'b', (Ax + Gx) / 2 - 22, (Ay + Gy) / 2 - 14, 16);
      italic(g, 'γ', Gx + 3, Gy - 12, 16);

      if (i === 0) {                       // (a) dangling a with gap
