        g.line(Gx, Gy, Gx, baseY).stroke({ color: DARK, width: 2 });
        g.polyline([Gx - 13, baseY, Gx - 13, baseY - 13, Gx, baseY - 13])
          .fill('none').stroke({ color: DARK, width: 1.5 });
        italic(g, 'a', Gx + 10, (Gy + baseY) / 2 - 6, 16);
        italic(g, 'β', Gx + 14, baseY + 4, 16);
      } else if (i === 2) {                // (c) altitude h + two dashed a
        g.line(Gx, Gy, Gx, baseY).stroke({ color: DARK, width: 2 });
        italic(g, 'h', Gx + 7, baseY - 30, 15);
        g.line(Gx, Gy, Gx - 46, baseY).stroke({ color: DARK, width: 2, dasharray: '6,4' });
        g.line(Gx, Gy, Gx + 50, baseY).stroke({ color: DARK, width: 2, dasharray: '6,4' });
        italic(g, 'a', Gx - 38, (Gy + baseY) / 2 - 14, 15);
