        g.line(Gx, Gy, Gx + 50, baseY).stroke({ color: DARK, width: 2, dasharray: '6,4' });
        italic(g, 'a', Gx - 38, (Gy + baseY) / 2 - 14, 15);
        italic(g, 'a', Gx + 42, (Gy + baseY) / 2 - 14, 15);
        italic(g, 'β', Gx + 62, baseY + 4, 16);
      } else {                             // (d) broad closed triangle
        g.line(Gx, Gy, Gx + 78, baseY).stroke({ color: DARK, width: 2 });
        italic(g, 'a', Gx + 50, (Gy + baseY) / 2 - 14, 16);
        italic(g, 'β', Gx + 90, baseY + 4, 16);
      }
      g.text(letters[i]).font({ size: 15, 'font-family': 'Georgia, serif' })
        .attr({ 'text-anchor': 'middle' }).center(ox + 96, 188);
    })(i);
  }
})();

/* ─────────── Bottom: live SSA construction ─────────── */
var ALPHA = Math.atan2(0.6, 0.8);          // ≈36.87°, sin α = 0.6
var B = 2.5, H = B * Math.sin(ALPHA);      // h = 1.5
var GX = B * Math.cos(ALPHA), GY = H;      // γ = (2.0, 1.5)
var S = 80, OX = 170, OY = 610;            // scale & origin
function px(wx) { return OX + S * wx; }
function py(wy) { return OY - S * wy; }

var a = 0.8, showH = true;
var live = draw.group();

function currentCase() {
  var EPS = 0.011;
  if (a < H - EPS) return 0;
  if (Math.abs(a - H) <= EPS) return 1;
  if (a < B - EPS) return 2;
  return 3;
}
var caseCaptions = [
  'a < h  →  No triangle',
  'a = h  →  One right triangle',
  'h < a < b  →  Two triangles',
  'a ≥ b  →  One triangle'
];
var caseColors = [HCOL, '#2e7d32', ACCENT, '#2e7d32'];

function redraw() {
  live.clear();
  var k = currentCase();
  var Ax = px(0), Ay = py(0), Gxp = px(GX), Gyp = py(GY);

  // faint arc showing where the tip of a can land
  live.circle(2 * a * S).center(Gxp, Gyp).fill('none')
    .stroke({ color: '#c4cbe0', width: 1.2, dasharray: '4,5' });

  // base line, angle α, side b, apex γ
  live.line(px(-0.7), Ay, px(4.2), Ay).stroke({ color: DARK, width: 2.5 });
  alphaArc(live, Ax, Ay, 40, ALPHA * 180 / PI, DARK, 1.8);
  live.text('α').font({ size: 20, 'font-style': 'italic', 'font-family': 'Georgia, serif' }).move(px(-0.42), Ay - 2);
  live.line(Ax, Ay, Gxp, Gyp).stroke({ color: DARK, width: 2.5 });
  live.text('b').font({ size: 20, 'font-style': 'italic', 'font-family': 'Georgia, serif' })
    .move((Ax + Gxp) / 2 - 34, (Ay + Gyp) / 2 - 12);
  live.text('γ').font({ size: 20, 'font-style': 'italic', 'font-family': 'Georgia, serif' })
    .move(Gxp + 8, Gyp - 26);

  // altitude h guide
  if (showH) {
    live.line(Gxp, Gyp, Gxp, Ay).stroke({ color: HCOL, width: 2, dasharray: '7,5' });
    live.polyline([Gxp - 12, Ay, Gxp - 12, Ay - 12, Gxp, Ay - 12])
      .fill('none').stroke({ color: HCOL, width: 1.5 });
    live.text('h').font({ size: 18, 'font-style': 'italic', 'font-family': 'Georgia, serif', fill: HCOL })
      .move(Gxp + 6, Ay - 46);
  }

  function blueSeg(x2, y2, dash) {
    var st = { color: ACCENT, width: 3.5, linecap: 'round' };
    if (dash) st.dasharray = '7,5';
    live.line(Gxp, Gyp, x2, y2).stroke(st);
  }
  function beta(x) {
    live.text('β').font({ size: 20, 'font-style': 'italic', 'font-family': 'Georgia, serif' })
      .move(x + 12, Ay - 2);
  }
  function tri(x2) {
    live.polygon([Ax, Ay, Gxp, Gyp, x2, Ay]).fill({ color: ACCENT, opacity: 0.14 }).stroke('none');
  }

  if (k === 0) {
    var tipY = py(H - a);
    blueSeg(Gxp, tipY);
    live.line(Gxp, tipY, Gxp, Ay).stroke({ color: HCOL, width: 2.5, dasharray: '5,4' });
    live.text('gap').font({ size: 14, fill: HCOL, 'font-style': 'italic' }).move(Gxp + 8, (tipY + Ay) / 2 - 8);
  } else if (k === 1) {
    tri(Gxp);
    blueSeg(Gxp, Ay);
    live.polyline([Gxp - 13, Ay, Gxp - 13, Ay - 13, Gxp, Ay - 13])
      .fill('none').stroke({ color: DARK, width: 1.8 });
    beta(Gxp);
  } else if (k === 2) {
    var dx2 = Math.sqrt(a * a - H * H);
    var xL = px(GX - dx2), xR = px(GX + dx2);
    tri(xL); tri(xR);
    blueSeg(xL, Ay); blueSeg(xR, Ay);
    live.circle(7).center(xL, Ay).fill(ACCENT);
    live.circle(7).center(xR, Ay).fill(ACCENT);
    live.text('a').font({ size: 17, 'font-style': 'italic', fill: ACCENT }).move((Gxp + xL) / 2 - 20, (Gyp + Ay) / 2 - 8);
    live.text('a').font({ size: 17, 'font-style': 'italic', fill: ACCENT }).move((Gxp + xR) / 2 + 10, (Gyp + Ay) / 2 - 8);
    beta(xR);
  } else {
    var dx3 = Math.sqrt(a * a - H * H);
    var xR3 = px(GX + dx3), xL3 = px(GX - dx3);
    tri(xR3);
    blueSeg(xR3, Ay);
    if (GX - dx3 < -0.02) {
      live.line(Gxp, Gyp, xL3, Ay).stroke({ color: '#999', width: 2, dasharray: '6,5' });
      live.text('✕').font({ size: 18, fill: HCOL }).center(xL3, Ay - 6);
      live.text('behind α — invalid').font({ size: 12, fill: HCOL }).move(xL3 + 10, Ay + 14);
    }
    live.text('a').font({ size: 17, 'font-style': 'italic', fill: ACCENT }).move((Gxp + xR3) / 2 + 10, (Gyp + Ay) / 2 - 8);
    beta(xR3);
  }

  // captions
  live.text(caseCaptions[k]).font({ size: 22, 'font-family': 'Georgia, serif', weight: 'bold', fill: caseColors[k] })
    .attr({ 'text-anchor': 'middle' }).center(450, 222);
  live.text('α = 36.9° (fixed)    b = 2.5 (fixed)    h = b·sin α = 1.50    a = ' + a.toFixed(2))
    .font({ size: 14, 'font-family': 'Georgia, serif', fill: '#333' })
    .attr({ 'text-anchor': 'middle' }).center(450, 250);
}

/* ─────────── Interactions ─────────── */
var caseValues = [0.8, 1.5, 2.1, 2.7];
var caseNames = ['No triangle (a < h)', 'Right triangle (a = h)', 'Two triangles (h < a < b)', 'One triangle (a ≥ b)'];
var caseIdx = 0;

function update_sideLengthA(v) {
  a = v;
  redraw();
}
function toggle_showAltitude(on) {
  showH = on;
  redraw();
}
function setCase(i) {
  caseIdx = i;
  var slider = document.getElementById('sideLengthAInput');
  slider.value = caseValues[i];
  document.getElementById('sideLengthAVal').value = caseValues[i];
  document.getElementById('caseStepperState').textContent = caseNames[i];
  update_sideLengthA(caseValues[i]);
}
function trigger_caseStepper() {
  setCase((caseIdx + 1) % 4);
}

/* ─────────── Demo step player ─────────── */
var demoSteps = [
  { title: 'No triangle: a < h', narration: 'Side a is shorter than the altitude h, the shortest possible distance from γ to the base — the segment dangles with a visible gap and no triangle can close.', a: 0.8 },
  { title: 'Right triangle: a = h', narration: 'When a exactly equals h, it just reaches the base at one perpendicular point — the right-angle marker appears and exactly one (right) triangle exists.', a: 1.5 },
  { title: 'Two triangles: h < a < b', narration: 'Now a is longer than h but shorter than b, so it can swing to the base on either side of the altitude foot — both positions close, giving two valid triangles.', a: 2.1 },
  { title: 'One triangle: a ≥ b', narration: 'Once a is at least as long as b, the left-hand landing point falls behind α and is no longer valid — only one triangle remains.', a: 2.7 },
  { title: 'Explore freely', narration: 'Drag the slider for a slowly and watch the construction pass through all four regimes; toggle the altitude off and on to confirm h is the boundary that separates "impossible" from "possible".', a: 1.5 }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(demoSteps.length - 1, i));
  var st = demoSteps[stepIdx];
  document.getElementById('demoNarration').textContent = st.title + ' — ' + st.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' of ' + demoSteps.length;
  document.getElementById('showAltitudeInput').checked = true;
  toggle_showAltitude(true);
  var slider = document.getElementById('sideLengthAInput');
  slider.value = st.a;
  document.getElementById('sideLengthAVal').value = st.a;
  update_sideLengthA(st.a);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

redraw();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: When two sides and a non-included angle (SSA) are given, comparing side a to the altitude h = b·sin(α) and to side b determines whether zero, one (right), two, or one triangle can be constructed.
KEY INSIGHT (what students should walk away understanding): The ambiguous case of SSA is fully resolved by two comparisons: a against h = b·sin(α) decides whether any triangle exists, and a against b decides whether one or two exist.
DEMO STEPS: 5 guided steps — implement the step player in #ui

