// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).viewbox(0, 0, 960, 780);
var PI = Math.PI;
var ACCENT = '#1565c0', HCOL = '#d32f2f', DARK = '#111';

/* One consistent angle everywhere: α = 40° in BOTH the static panels and the
   live construction, so the figure is internally consistent. */
var ALPHA_DEG = 40;
var ALPHA = ALPHA_DEG * PI / 180;

/* ─────────── Top: four faithful panels (enlarged) ─────────── */
var headings = ['No triangle, a < h', 'Right triangle, a = h', 'Two triangles, a > h, a < b', 'One triangle, a ≥ b'];
var letters = ['(a)', '(b)', '(c)', '(d)'];
var popups = [
  ['No triangle (a < h)', 'Side a is shorter than the altitude h = b·sin α, the closest γ ever gets to the base. The segment dangles with a gap, so the figure can never close — no triangle exists.'],
  ['Right triangle (a = h)', 'When a exactly equals h, it just touches the base at the one perpendicular point. Exactly one triangle exists, and it is a right triangle.'],
  ['Two triangles (h < a < b)', 'Side a is long enough to reach the base but shorter than b, so it can swing down on either side of the altitude foot. Both positions close — two different triangles satisfy the same SSA data.'],
  ['One triangle (a ≥ b)', 'Once a is at least as long as b, the left-hand landing point falls behind α and is not valid. Only one triangle remains — the SSA ambiguity disappears.']
];

function italic(g, str, x, y, size, anchor) {
  return g.text(str).font({ size: size || 16, 'font-style': 'italic', 'font-family': 'Georgia, serif' })
    .attr({ 'text-anchor': anchor || 'start', fill: DARK, 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' }).move(x, y);
}
function alphaArc(g, cx, cy, r, angDeg, col, w) {
  var t = angDeg * PI / 180;
  g.path('M ' + (cx + r) + ' ' + cy + ' A ' + r + ' ' + r + ' 0 0 0 ' +
    (cx + r * Math.cos(t)) + ' ' + (cy - r * Math.sin(t)))
    .fill('none').stroke({ color: col || DARK, width: w || 1.5 });
}

(function drawPanels() {
  var baseY = 165, bpx = 120;
  var panelW = 236;                       // wider panels so (c) is not cramped
  var c = Math.cos(ALPHA), s = Math.sin(ALPHA);
  for (var i = 0; i < 4; i++) {
    (function (i) {
      var ox = 10 + i * panelW;
      var g = draw.group().css('cursor', 'pointer');
      g.on('click', function () { showPopup(popups[i][0], popups[i][1]); });
      g.text(headings[i]).font({ size: 14.5, 'font-family': 'Georgia, serif' })
        .attr({ 'text-anchor': 'middle' }).center(ox + panelW / 2, 24);
      var Ax = ox + 16, Ay = baseY;
      var Gx = Ax + bpx * c, Gy = Ay - bpx * s;
      // base + angle α + side b + apex label
      g.line(ox + 2, baseY, ox + panelW - 26, baseY).stroke({ color: DARK, width: 2 });
      alphaArc(g, Ax, Ay, 24, ALPHA_DEG);
      italic(g, 'α', ox - 4, baseY + 4, 16);
      g.line(Ax, Ay, Gx, Gy).stroke({ color: DARK, width: 2 });
      italic(g, 'b', (Ax + Gx) / 2 - 26, (Ay + Gy) / 2 - 16, 16);
      italic(g, 'γ', Gx + 4, Gy - 14, 16);

      if (i === 0) {                       // (a) dangling a with gap
        g.line(Gx, Gy, Gx, baseY - 36).stroke({ color: DARK, width: 2 });
        italic(g, 'a', Gx + 10, (Gy + baseY - 36) / 2 - 7, 16);
        italic(g, 'β', Gx + 16, baseY + 4, 16);
      } else if (i === 1) {                // (b) a = h, right angle
        g.line(Gx, Gy, Gx, baseY).stroke({ color: DARK, width: 2 });
        g.polyline([Gx - 13, baseY, Gx - 13, baseY - 13, Gx, baseY - 13])
          .fill('none').stroke({ color: DARK, width: 1.5 });
        italic(g, 'a', Gx + 10, (Gy + baseY) / 2 - 7, 16);
        italic(g, 'β', Gx + 14, baseY + 4, 16);
      } else if (i === 2) {                // (c) altitude h + two dashed a
        g.line(Gx, Gy, Gx, baseY).stroke({ color: DARK, width: 2 });
        italic(g, 'h', Gx + 8, baseY - 34, 15);
        g.line(Gx, Gy, Gx - 48, baseY).stroke({ color: DARK, width: 2, dasharray: '6,4' });
        g.line(Gx, Gy, Gx + 52, baseY).stroke({ color: DARK, width: 2, dasharray: '6,4' });
        italic(g, 'a', Gx - 42, (Gy + baseY) / 2 - 18, 15);
        italic(g, 'a', Gx + 44, (Gy + baseY) / 2 - 18, 15);
        italic(g, 'β', Gx + 64, baseY + 4, 16);
      } else {                             // (d) broad closed triangle
        g.line(Gx, Gy, Gx + 84, baseY).stroke({ color: DARK, width: 2 });
        italic(g, 'a', Gx + 54, (Gy + baseY) / 2 - 16, 16);
        italic(g, 'β', Gx + 96, baseY + 4, 16);
      }
      g.text(letters[i]).font({ size: 15, 'font-family': 'Georgia, serif' })
        .attr({ 'text-anchor': 'middle' }).center(ox + panelW / 2, 200);
    })(i);
  }
})();

/* ─────────── Bottom: live SSA construction ─────────── */
var B = 2.5, H = B * Math.sin(ALPHA);      // h = b·sin 40° ≈ 1.607
var GX = B * Math.cos(ALPHA), GY = H;
var S = 80, OX = 170, OY = 630;            // scale & origin
function px(wx) { return OX + S * wx; }
function py(wy) { return OY - S * wy; }

var a = 0.8, showH = true;
var live = draw.group();

function currentCase() {
  var EPS = 0.011;
  if (a < H - EPS) return 0;
  if (Math.abs(a - H) <= EPS) return 1;
  if (a < B - EPS) return 2;
  return 3;
}
var caseCaptions = [
  'a < h  →  No triangle',
  'a = h  →  One right triangle',
  'h < a < b  →  Two triangles',
  'a ≥ b  →  One triangle'
];
var caseColors = [HCOL, '#2e7d32', ACCENT, '#2e7d32'];

function redraw() {
  live.clear();
  var k = currentCase();
  var Ax = px(0), Ay = py(0), Gxp = px(GX), Gyp = py(GY);

  // faint compass arc showing where the tip of a can land
  live.circle(2 * a * S).center(Gxp, Gyp).fill('none')
    .stroke({ color: '#c4cbe0', width: 1.2, dasharray: '4,5' });

  // base line, angle α, side b, apex γ
  live.line(px(-0.7), Ay, px(4.3), Ay).stroke({ color: DARK, width: 2.5 });
  alphaArc(live, Ax, Ay, 40, ALPHA_DEG, DARK, 1.8);
  live.text('α').font({ size: 20, 'font-style': 'italic', 'font-family': 'Georgia, serif' }).move(px(-0.42), Ay - 2);
  live.line(Ax, Ay, Gxp, Gyp).stroke({ color: DARK, width: 2.5 });
  live.text('b').font({ size: 20, 'font-style': 'italic', 'font-family': 'Georgia, serif' })
    .move((Ax + Gxp) / 2 - 36, (Ay + Gyp) / 2 - 12);
  live.text('γ').font({ size: 20, 'font-style': 'italic', 'font-family': 'Georgia, serif' })
    .move(Gxp + 8, Gyp - 26);

  // altitude h guide
  if (showH) {
    live.line(Gxp, Gyp, Gxp, Ay).stroke({ color: HCOL, width: 2, dasharray: '7,5' });
    live.polyline([Gxp - 12, Ay, Gxp - 12, Ay - 12, Gxp, Ay - 12])
      .fill('none').stroke({ color: HCOL, width: 1.5 });
    live.text('h').font({ size: 18, 'font-style': 'italic', 'font-family': 'Georgia, serif', fill: HCOL })
      .move(Gxp + 6, Ay - 48);
  }

  function blueSeg(x2) {
    live.line(Gxp, Gyp, x2, Ay).stroke({ color: ACCENT, width: 3.5, linecap: 'round' });
  }
  function beta(x) {
    live.text('β').font({ size: 20, 'font-style': 'italic', 'font-family': 'Georgia, serif' })
      .move(x + 12, Ay - 2);
  }
  function tri(x2) {
    live.polygon([Ax, Ay, Gxp, Gyp, x2, Ay]).fill({ color: ACCENT, opacity: 0.14 }).stroke('none');
  }

  if (k === 0) {
    var tipY = py(H - a);
    blueSeg(Gxp);
    live.node.lastChild.setAttribute('y2', tipY); // segment stops above base
    // gap drawn as a light annotation, not a geometric element
    live.line(Gxp, tipY, Gxp, Ay).stroke({ color: '#e0a3a3', width: 1.5, dasharray: '2,4' });
    live.text('(gap: a < h)').font({ size: 12, fill: '#c07', 'font-style': 'italic' })
      .move(Gxp + 10, (tipY + Ay) / 2 - 7);
  } else if (k === 1) {
    tri(Gxp);
    blueSeg(Gxp);
    live.polyline([Gxp - 13, Ay, Gxp - 13, Ay - 13, Gxp, Ay - 13])
      .fill('none').stroke({ color: DARK, width: 1.8 });
    beta(Gxp);
  } else if (k === 2) {
    var dx2 = Math.sqrt(a * a - H * H);
    var xL = px(GX - dx2), xR = px(GX + dx2);
    tri(xL); tri(xR);
    blueSeg(xL); blueSeg(xR);
    live.circle(7).center(xL, Ay).fill(ACCENT);
    live.circle(7).center(xR, Ay).fill(ACCENT);
    live.text('a').font({ size: 17, 'font-style': 'italic', fill: ACCENT }).move((Gxp + xL) / 2 - 22, (Gyp + Ay) / 2 - 8);
    live.text('a').font({ size: 17, 'font-style': 'italic', fill: ACCENT }).move((Gxp + xR) / 2 + 10, (Gyp + Ay) / 2 - 8);
    beta(xR);
  } else {
    var dx3 = Math.sqrt(a * a - H * H);
    var xR3 = px(GX + dx3), xL3 = px(GX - dx3);
    tri(xR3);
    blueSeg(xR3);
    if (GX - dx3 < -0.02) {
      live.line(Gxp, Gyp, xL3, Ay).stroke({ color: '#999', width: 2, dasharray: '6,5' });
      live.text('✕').font({ size: 18, fill: HCOL }).center(xL3, Ay - 6);
      live.text('behind α — invalid').font({ size: 12, fill: HCOL }).move(xL3 + 10, Ay + 14);
    }
    live.text('a').font({ size: 17, 'font-style': 'italic', fill: ACCENT }).move((Gxp + xR3) / 2 + 10, (Gyp + Ay) / 2 - 8);
    beta(xR3);
  }

  // captions
  live.text(caseCaptions[k]).font({ size: 22, 'font-family': 'Georgia, serif', weight: 'bold', fill: caseColors[k] })
    .attr({ 'text-anchor': 'middle' }).center(470, 236);
  live.text('α = 40° (fixed)    b = 2.5 (fixed)    h = b·sin α ≈ ' + H.toFixed(2) + '    a = ' + a.toFixed(2))
    .font({ size: 14, 'font-family': 'Georgia, serif', fill: '#333' })
    .attr({ 'text-anchor': 'middle' }).center(470, 264);
}

/* ─────────── Interactions ─────────── */
var caseValues = [0.8, H, 2.1, 2.7];
var caseNames = ['No triangle (a < h)', 'Right triangle (a = h)', 'Two triangles (h < a < b)', 'One triangle (a ≥ b)'];
var caseIdx = -1;   // start before case 0 so the first click lands on 'No triangle (a < h)'

function update_sideLengthA(v) {
  a = v;
  redraw();
}
function toggle_showAltitude(on) {
  showH = on;
  redraw();
}
function setCase(i) {
  caseIdx = i;
  var slider = document.getElementById('sideLengthAInput');
  slider.value = caseValues[i];
  document.getElementById('sideLengthAVal').value = (+caseValues[i]).toFixed(2);
  document.getElementById('caseStepperState').textContent = caseNames[i];
  update_sideLengthA(caseValues[i]);
}
function trigger_caseStepper() {
  setCase((caseIdx + 1) % 4);
}

/* ─────────── Demo step player ─────────── */
var demoSteps = [
  { title: 'No triangle: a < h', narration: 'Side a is shorter than the altitude h, the shortest possible distance from γ to the base — the segment dangles with a visible gap and no triangle can close.', a: 0.8 },
  { title: 'Right triangle: a = h', narration: 'When a exactly equals h, it just reaches the base at one perpendicular point — the right-angle marker appears and exactly one (right) triangle exists.', a: H },
  { title: 'Two triangles: h < a < b', narration: 'Now a is longer than h but shorter than b, so it can swing to the base on either side of the altitude foot — the two positions both close, giving two valid triangles.', a: 2.1 },
